{
  "themes": [
    {
      "name": "Queue and lobby wait times",
      "summary": "Players report long matchmaking and lobby waits. Some spend more time waiting than playing, and long queues are causing friends to quit.",
      "severity": "high",
      "comments": [
        {"id": "c029", "quote": "waited 17 mins to get in"},
        {"id": "c059", "quote": "Spent more time in the lobby than in the match"},
        {"id": "c080", "quote": "watching the searching for match spinner"},
        {"id": "c091", "quote": "half an hour per game is rough"},
        {"id": "c089", "quote": "another 30 minute queue"}
      ]
    },
    {
      "name": "Performance and stutter",
      "summary": "Players report low frame rates and stutters during matches. Some see good menu performance but poor in match performance, even after lowering settings.",
      "severity": "high",
      "comments": [
        {"id": "c040", "quote": "drop to 40fps on Greywater when it rains"},
        {"id": "c107", "quote": "70 fps in the menu and 25 in the match"},
        {"id": "c055", "quote": "big stutter right as i respawn"}
      ]
    },
    {
      "name": "Spawn safety",
      "summary": "Players report spawning in dangerous positions or next to enemies. They die immediately and feel spawns are unsafe.",
      "severity": "high",
      "comments": [
        {"id": "c105", "quote": "died 4 times before i took a single step"},
        {"id": "c032", "quote": "spawned right in front of their whole team"},
        {"id": "c010", "quote": "spawning right in front of the enemy sniper"},
        {"id": "c008", "quote": "being dropped next to 3 enemies with full health"}
      ]
    },
    {
      "name": "Ability VFX readability",
      "summary": "Players report ability effects, traps, and ult warnings are too faint or blend into the background. This makes them hard to see and dodge in fights.",
      "severity": "high",
      "comments": [
        {"id": "c042", "quote": "slow field has no visible edge"},
        {"id": "c117", "quote": "shock trap needs a bigger tell"},
        {"id": "c069", "quote": "ult warning is a small glow at the feet"},
        {"id": "c022", "quote": "spell effects blend in with the background"},
        {"id": "c019", "quote": "ability vfx are so faint"},
        {"id": "c012", "quote": "Can't see half the ability effects"}
      ]
    },
    {
      "name": "Voice chat toxicity",
      "summary": "Players report harassment, slurs, and toxic voice chat. Some have muted voice or stopped using it entirely.",
      "severity": "high",
      "comments": [
        {"id": "c037", "quote": "heard things on team chat"},
        {"id": "c100", "quote": "got called slurs in voice"},
        {"id": "c054", "quote": "non stop harassment"},
        {"id": "c096", "quote": "sexist comments on comms"},
        {"id": "c114", "quote": "mic toxicity is out of control"},
        {"id": "c078", "quote": "hurling insults on voice"}
      ]
    },
    {
      "name": "Progression and currency grind",
      "summary": "Players report XP, shards, and gear progression are too slow. Unlocks and ranked preparation feel grindy.",
      "severity": "high",
      "comments": [
        {"id": "c065", "quote": "Progress is way too slow"},
        {"id": "c120", "quote": "XP per match is tiny"},
        {"id": "c002", "quote": "morrow locked behind 15000 shards"},
        {"id": "c030", "quote": "grind to get the good gear before ranked is just boring"},
        {"id": "c011", "quote": "shards drop so slow"}
      ]
    },
    {
      "name": "Onboarding and tutorial clarity",
      "summary": "Players report the tutorial and onboarding are rushed and unclear. Key mechanics like cooldowns, overcharge, and ult charge are not explained well.",
      "severity": "medium",
      "comments": [
        {"id": "c088", "quote": "onboarding assumes you already played hero shooters"},
        {"id": "c013", "quote": "training bit rushes thru like 10 mechanics in 3 mins"},
        {"id": "c036", "quote": "wtf is overcharge?"},
        {"id": "c023", "quote": "no explanation how to charge it"}
      ]
    },
    {
      "name": "UI and menu discoverability",
      "summary": "Players report menus and icons are confusing and hard to navigate. Common actions like keybinds and invites are difficult to find.",
      "severity": "medium",
      "comments": [
        {"id": "c057", "quote": "cursor jumps around the menu in ways I can't predict"},
        {"id": "c041", "quote": "main menu has 14 buttons on it"},
        {"id": "c066", "quote": "couldnt find keybinds for ages"},
        {"id": "c090", "quote": "what do all these icons mean"},
        {"id": "c077", "quote": "cant figure out how to invite a friend"}
      ]
    }
  ],
  "unassigned": [
    "c086",
    "c050"
  ]
}
